using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Seamless.FLinq;

namespace Test.SourceGenerator.OrderedFirstDemand;

[LinqIntercept(false)]
public sealed class OrderingBase{
    private const string OriginalInputSHA256="C7CAE3D4B24BDD0D9B4346F184D3D6EF01F875E0EF813717AF3FB86BC437BCAC";
    private const string OriginalOracleSHA256="41845FAA6FFF0B85F0F50A433B51B2F16793809F40A62932BA0C9265BEE1F0B8";
    private const string OriginalBase64="";
    private const string OriginalOracleBase64="";
    // 元CSVを保持し、Systemの保存済み列挙traceから誤期待だけを訂正する。
    private const string EffectiveOracleSHA256="D0E6378435CFC65A224E7A4581B65EB0964BE9A55A0CC8C19F0B120EE2C20E5D";
    private const string EffectiveOracleBase64="";
    // 追加の構文木とし、26のソースbytes、query本体、Anchorを変更しない。
    private const string GBaseHeader="global using System; global using System.Collections; global using System.Collections.Generic; global using System.IO; global using System.Linq; global using System.Net.Http; global using System.Threading; global using System.Threading.Tasks;";
    // 元queryとは別の構文木で、返却・反復・throwの列挙境界を観測する。
    private const string EscapedLifecycleBase64="";
    private sealed record Oracle(string Name,string SingletonValue,string SingletonTrace,long LogicalDelegate,bool KeyThrowsOnSingleton,string EmptyOutcome);
    private sealed record Observation(string Value,string ExceptionType,string Trace,long LogicalDelegate,long PhysicalDelegate,long Fallback);
    private static string Hash(byte[] value)=>Convert.ToHexString(SHA256.HashData(value));
    private static void Save(string name,string text){
        var directory=Environment.GetEnvironmentVariable("SEAMLESS_ORDERED_FIRST_DEMAND_ARTIFACT_DIR");
        if(string.IsNullOrWhiteSpace(directory)){throw new InvalidOperationException("SEAMLESS_ORDERED_FIRST_DEMAND_ARTIFACT_DIR is required");}
        Directory.CreateDirectory(directory);File.WriteAllText(Path.Combine(directory,name),text,new UTF8Encoding(false));
    }
    private static Oracle[] ReadOracle(byte[] bytes){
        var lines=Encoding.UTF8.GetString(bytes).Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries);
        Assert.Equal("Consumer,SingletonValue,SingletonTrace,LogicalDelegate,KeyThrowsOnSingleton,EmptyOutcome",lines[0]);
        return lines.Skip(1).Select(line=>{
            var x=line.Split(',');Assert.Equal(6,x.Length);
            return new Oracle(x[0],x[1],x[2].Replace(';',','),long.Parse(x[3],global::System.Globalization.CultureInfo.InvariantCulture),bool.Parse(x[4]),x[5]);
        }).ToArray();
    }
    [Fact]
    public void SystemNoneAllRespectOrderedFirstDemand(){
        var input=Convert.FromBase64String(OriginalBase64);var originalCsv=Convert.FromBase64String(OriginalOracleBase64);var csv=Convert.FromBase64String(EffectiveOracleBase64);
        Assert.Equal(OriginalInputSHA256,Hash(input));Assert.Equal(OriginalOracleSHA256,Hash(originalCsv));Assert.Equal(EffectiveOracleSHA256,Hash(csv));
        var source=Encoding.UTF8.GetString(input);var oracle=ReadOracle(csv);Assert.Equal(10,oracle.Length);
        Save("input.cs",source);Save("oracle-original.csv",Encoding.UTF8.GetString(originalCsv));Save("oracle.csv",Encoding.UTF8.GetString(csv));Save("global-header.cs",GBaseHeader);
        var options=new CSharpParseOptions(LanguageVersion.Preview).WithFeatures([
            new("InterceptorsPreview","true"),new("InterceptorsNamespaces","Intercept"),new("InterceptorsPreviewNamespaces","Intercept")]);
        var compilation=global::Test.SourceGenerator.GeneratorTestHelpers.CreateCompilation([("OrderingInput.cs",source),("GBaseHeader.cs",GBaseHeader)]).WithAssemblyName("OrderedFirstDemand");
        compilation=compilation.RemoveAllSyntaxTrees().AddSyntaxTrees(compilation.SyntaxTrees.Select(tree=>CSharpSyntaxTree.ParseText(tree.ToString(),options,path:tree.FilePath)));
        GeneratorDriver driver=CSharpGeneratorDriver.Create([new global::Seamless.FLinq.Generator.FLinqIncrementalGenerator().AsSourceGenerator()],parseOptions:options);
        driver=driver.RunGeneratorsAndUpdateCompilation(compilation,out var output,out var generatorDiagnostics);
        var generated=string.Concat(output.SyntaxTrees.Skip(compilation.SyntaxTrees.Count()).Select(tree=>tree.ToString()));Save("generated.cs",generated);
        using var pe=new MemoryStream();var emit=output.Emit(pe);
        var diagnostics=generatorDiagnostics.Concat(output.GetDiagnostics()).Concat(emit.Diagnostics).Select(x=>new{x.Id,Severity=x.Severity.ToString(),Text=x.ToString()}).ToArray();
        var errors=diagnostics.Where(x=>x.Severity=="Error").ToArray();var intercepts=generated.Split("InterceptsLocationAttribute(1,",StringSplitOptions.None).Length-1;
        var unsupported=generated.Contains("UnsupportedLinqExpansion(",StringComparison.Ordinal);
        Save("compilation.json",JsonSerializer.Serialize(new{CounterDefinition="visible-query-lambdas-entry-total-v2",OnExceptionTiming="entry",PreviousCounterDefinition="visible-query-lambdas-total-v1",PreviousOnExceptionTiming="legacy path dependent; not unified",OriginalInputSHA256=Hash(input),OriginalOracleSHA256=Hash(originalCsv),EffectiveOracleSHA256=Hash(csv),OracleSHA256=Hash(csv),HeaderSHA256=Hash(Encoding.UTF8.GetBytes(GBaseHeader)),GeneratedSHA256=Hash(Encoding.UTF8.GetBytes(generated)),EmittedAssemblySHA256=Hash(pe.ToArray()),GeneratorSHA256=Hash(File.ReadAllBytes(typeof(global::Seamless.FLinq.Generator.FLinqIncrementalGenerator).Assembly.Location)),TestAssemblySHA256=Hash(File.ReadAllBytes(typeof(OrderingBase).Assembly.Location)),RuntimeAssemblySHA256=Hash(File.ReadAllBytes(typeof(global::Seamless.Linq.GeneratedCodeHelpers).Assembly.Location)),emit.Success,intercepts,unsupported,diagnostics}));
        Assert.Empty(errors);Assert.True(emit.Success);Assert.True(intercepts>=20,"None/All 20 query calls must be intercepted");Assert.False(unsupported,"unsupported fallback is not accepted");
        var records=new List<object>();var failures=new List<string>();var context=new global::System.Runtime.Loader.AssemblyLoadContext("OrderedFirstDemand",isCollectible:true);
        try{
            pe.Position=0;var method=context.LoadFromStream(pe).GetType("Sample.Probe")!.GetMethod("Run")!;
            int[][] shapes=[[],[7],[2,1],[2,2]];
            for(var consumer=0;consumer<10;consumer++){
                foreach(var values in shapes){foreach(var throwKey in new[]{false,true}){
                    var reference=Read(method,0,consumer,values,throwKey);var row=oracle[consumer];var before=failures.Count;
                    // 最初にCSVをSystemと照合し、実装由来の期待値補正は行わない。
                    if(values.Length==0){
                        string expectedError;
                        if(row.EmptyOutcome=="InvalidOperationException"){expectedError="InvalidOperationException";}else{expectedError="";}
                        string expectedValue;
                        if(expectedError!=""||row.EmptyOutcome=="empty"){expectedValue="";}else{expectedValue=row.EmptyOutcome;}
                        Check(reference.Value==expectedValue&&reference.ExceptionType==expectedError&&reference.Trace=="",consumer,values,throwKey,"System CSV empty",failures);
                    }else if(values.Length==1){
                        var shouldThrow=throwKey&&row.KeyThrowsOnSingleton;
                        string expectedTrace;
                        if(shouldThrow){expectedTrace="K:7";}else{expectedTrace=row.SingletonTrace;}
                        string expectedReferenceValue;
                        string expectedExceptionType;
                        if(shouldThrow){expectedReferenceValue="";expectedExceptionType="InvalidOperationException";}else{expectedReferenceValue=row.SingletonValue;expectedExceptionType="";}
                        Check(reference.Value==expectedReferenceValue&&reference.ExceptionType==expectedExceptionType&&reference.Trace==expectedTrace,consumer,values,throwKey,"System CSV singleton",failures);
                        if(!shouldThrow){Check(CountTrace(reference.Trace)==row.LogicalDelegate,consumer,values,throwKey,"System CSV singleton delegate count",failures);}
                    }
                    var systemOracleFailures=failures.Skip(before).ToArray();
                    for(var mode=1;mode<=2;mode++){
                        var actual=Read(method,mode,consumer,values,throwKey);var modeStart=failures.Count;
                        Check(actual.Value==reference.Value&&actual.ExceptionType==reference.ExceptionType&&actual.Trace==reference.Trace,consumer,values,throwKey,"mode "+mode+" System value/exception/trace",failures);
                        Check(actual.LogicalDelegate==CountTrace(actual.Trace)&&actual.PhysicalDelegate==0&&actual.Fallback==0,consumer,values,throwKey,"mode "+mode+" logical/physical/fallback",failures);
                        records.Add(new{consumer,values,throwKey,mode,oracle=row,reference,actual,systemOracleFailures,modeFailures=failures.Skip(modeStart).ToArray()});
                    }
                }}
            }
        }finally{context.Unload();Save("observations.json",JsonSerializer.Serialize(new{CounterDefinition="visible-query-lambdas-entry-total-v2",OnExceptionTiming="entry",PreviousCounterDefinition="visible-query-lambdas-total-v1",PreviousOnExceptionTiming="legacy path dependent; not unified",expectedComparisons=160,actualComparisons=records.Count,records,failures},new JsonSerializerOptions{WriteIndented=true}));}
        Assert.Equal(160,records.Count);Assert.Empty(failures);
    }
    [Fact]
    public void EscapedOrderedArrayRemainsDeferredAndReiterable(){
        var input=Convert.FromBase64String(OriginalBase64);Assert.Equal(OriginalInputSHA256,Hash(input));
        var source=Encoding.UTF8.GetString(input);
        var lifecycleSource=Convert.FromBase64String(EscapedLifecycleBase64);
        var lifecycleText=Encoding.UTF8.GetString(lifecycleSource);
        Save("lifecycle-input-original.cs",source);Save("lifecycle-probe.cs",lifecycleText);
        var options=new CSharpParseOptions(LanguageVersion.Preview).WithFeatures([
            new("InterceptorsPreview","true"),new("InterceptorsNamespaces","Intercept"),new("InterceptorsPreviewNamespaces","Intercept")]);
        var compilation=global::Test.SourceGenerator.GeneratorTestHelpers.CreateCompilation([("OrderingInput.cs",source),("GBaseHeader.cs",GBaseHeader),("Lifecycle.cs",lifecycleText)]).WithAssemblyName("OrderedEscapedLifecycle");
        compilation=compilation.RemoveAllSyntaxTrees().AddSyntaxTrees(compilation.SyntaxTrees.Select(tree=>CSharpSyntaxTree.ParseText(tree.ToString(),options,path:tree.FilePath)));
        GeneratorDriver driver=CSharpGeneratorDriver.Create([new global::Seamless.FLinq.Generator.FLinqIncrementalGenerator().AsSourceGenerator()],parseOptions:options);
        driver=driver.RunGeneratorsAndUpdateCompilation(compilation,out var output,out var generatorDiagnostics);
        var generated=string.Concat(output.SyntaxTrees.Skip(compilation.SyntaxTrees.Count()).Select(tree=>tree.ToString()));Save("lifecycle-generated.cs",generated);
        using var pe=new MemoryStream();var emit=output.Emit(pe);
        var errors=generatorDiagnostics.Concat(output.GetDiagnostics()).Concat(emit.Diagnostics).Where(x=>x.Severity==DiagnosticSeverity.Error).Select(x=>x.ToString()).ToArray();
        Save("lifecycle-compilation.json",JsonSerializer.Serialize(new{CounterDefinition="visible-query-lambdas-entry-total-v2",OnExceptionTiming="entry",PreviousCounterDefinition="visible-query-lambdas-total-v1",PreviousOnExceptionTiming="legacy path dependent; not unified",OriginalInputSHA256=Hash(input),LifecycleSHA256=Hash(lifecycleSource),GeneratedSHA256=Hash(Encoding.UTF8.GetBytes(generated)),EmittedAssemblySHA256=Hash(pe.ToArray()),GeneratorSHA256=Hash(File.ReadAllBytes(typeof(global::Seamless.FLinq.Generator.FLinqIncrementalGenerator).Assembly.Location)),TestAssemblySHA256=Hash(File.ReadAllBytes(typeof(OrderingBase).Assembly.Location)),RuntimeAssemblySHA256=Hash(File.ReadAllBytes(typeof(global::Seamless.Linq.GeneratedCodeHelpers).Assembly.Location)),emit.Success,errors}));
        Assert.Empty(errors);Assert.True(emit.Success);Assert.DoesNotContain("UnsupportedLinqExpansion(",generated,StringComparison.Ordinal);
        // 可視keyをBCLのlambdaのまま残したinterceptorは、countだけを増やしても受け入れない。
        Assert.DoesNotContain("values.OrderBy(value=>state.Key(value))",generated,StringComparison.Ordinal);
        var context=new global::System.Runtime.Loader.AssemblyLoadContext("OrderedEscapedLifecycle",isCollectible:true);
        var records=new List<object>();
        try{
            pe.Position=0;var method=context.LoadFromStream(pe).GetType("Sample.LifecycleProbe")!.GetMethod("Run")!;
            for(var mode=0;mode<=2;mode++){
                var row=(object[])method.Invoke(null,[mode])!;records.Add(new{mode,row});
                Assert.Equal("",row[0]);Assert.Equal(0L,row[1]);Assert.Equal("",row[2]);Assert.Equal(0L,row[3]);
                Assert.Equal(true,row[4]);Assert.Equal(9,row[5]);Assert.Equal("K:9",row[6]);
                Assert.Equal("9",row[7]);Assert.Equal("K:9,K:9",row[8]);Assert.Equal("K:9,K:9",row[9]);
                Assert.Equal("InvalidOperationException:key",row[10]);Assert.Equal("K:9,K:9,K:9",row[11]);
                long expectedLogical=0;if(mode>0){expectedLogical=3;}
                Assert.Equal(expectedLogical,row[12]);Assert.Equal(0L,row[13]);Assert.Equal(0L,row[14]);
            }
        }finally{context.Unload();Save("lifecycle-observations.json",JsonSerializer.Serialize(new{CounterDefinition="visible-query-lambdas-entry-total-v2",OnExceptionTiming="entry",records}));}
    }
    private static long CountTrace(string trace){
        if(trace.Length==0){return 0;}
        long count=0;foreach(var entry in trace.Split(',')){if(entry.StartsWith("K:",StringComparison.Ordinal)||entry.StartsWith("T:",StringComparison.Ordinal)||entry.StartsWith("P:",StringComparison.Ordinal)){count++;}else{throw new InvalidOperationException("Unexpected trace entry: "+entry);}}return count;
    }
    private static Observation Read(global::System.Reflection.MethodInfo method,int mode,int consumer,int[] values,bool throwKey){
        var row=(object[])method.Invoke(null,[mode,consumer,values,throwKey])!;var error=(string)row[1];var separator=error.IndexOf(':');if(separator>=0){error=error[..separator];}
        return new((string)row[0],error,(string)row[2],(long)row[3],(long)row[4],(long)row[5]);
    }
    private static void Check(bool condition,int consumer,int[] values,bool throwKey,string reason,List<string> failures){if(!condition){failures.Add($"C{consumer} [{string.Join(",",values)}] throwKey={throwKey}: {reason}");}}
}
